import os
import logging
import tarfile
from random import randint
from binascii import hexlify
from cryptography import x509
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import hashes
from collections import OrderedDict

from taf.gnb.oam.ne3s.ws.components.CERT.v1.resources.notifications.messages import (
    CertOperationNotification, CertNotificationGroup,
    CMPOperationNotification, CRLOperationNotification
)
from taf.gnb.oam.ne3s.ws.components.connection.ne3s_service import NE3SService
from taf.gnb.oam.ne3s.ws.components.base import FunctionalComponent

from taf.gnb.oam.ne3s.ws.components.CERT.v1.resources.templates import templates
from taf.gnb.oam.ne3s.ws.exceptions import StreamTimeoutError
from taf.gnb.oam.ne3s.ws.components.exceptions import OperationTimeout, OperationFailed

from io import BytesIO as BIO

log = logging.getLogger("taf.gnb.oam.ne3s.ws.logger")


class CERTv1(FunctionalComponent):
    STREAMS = None
    _connection = None
    SUPPORTED_NOTIFICATIONS = CertNotificationGroup
    CMP_INITIALIZATION_REQUEST = 1
    CMP_KEY_UPDATE_REQUEST = 5
    CRL_UPDATE_REQUEST = 1
    CRLH = "CRLH"
    CMP = "CMP"

    def __init__(self, connection):
        self._connection = connection
        self.STREAMS = []

    def install_cert(self, cert_dist_name, path_to_cert, timeout):
        stream_name = "CERT.install_cert"
        filename = os.path.basename(path_to_cert)

        cert_install_stream = self.add_new_msg_stream(stream_name=stream_name,
                                                      msg_list=[CertOperationNotification])
        try:
            provision_content = templates.get_file_content('cert_install.txt', 'r')

            cert_fingerprint = self._generate_fingerprint(path_to_cert)

            log.info('Fingerprint (needed to delete this CERT): {}'.format(cert_fingerprint))

            dist_name = '{cert_dist_name}/CACERT-{cert_fingerprint}'.format(
                cert_dist_name=cert_dist_name,
                cert_fingerprint=cert_fingerprint)

            provision_content = provision_content.format(
                dist_name=dist_name,
                filename=filename
            )

            random_number = randint(int(10e4), int(10e5))
            provision_filename = 'cert_provision_content{}.xml'.format(random_number)
            cert_content = self._return_certificate_content(path_to_cert)
            tar_content = self._convert_to_tar_archive_string(list_of_files=[provision_content, cert_content],
                                                              cert_filename=filename,
                                                              provision_filename=provision_filename)

            log.info("Provision content: {}".format(tar_content.decode('utf-8')))

            self.cert_provision(provision_content=tar_content.decode('utf-8'), compression='tar',
                                primary_document=provision_filename)

            notification = cert_install_stream.get(timeout)

            if not self._is_validation_successful(notification):
                raise OperationFailed(notification.attachment)

        except StreamTimeoutError as e:
            err_msg = "Certificate installation confirmation was not provided in requested time, Error: {}".format(e)
            raise OperationTimeout(err_msg)

        finally:
            self.remove_msg_stream(stream_name=stream_name)

    def _is_validation_successful(self, notification):
        is_param_change_notification = isinstance(notification, CertOperationNotification)
        return is_param_change_notification and notification.attachment.status == 'ok'

    def _is_cmp_crl_validation_successful(self, notification):
        is_param_change_notification = isinstance(notification, CMPOperationNotification)
        is_crl_change_notification = isinstance(notification, CRLOperationNotification)
        return (is_param_change_notification or is_crl_change_notification) and notification.attachment.status == 'ok'

    def cert_provision(self, provision_content, compression='none', primary_document='cert_provision_content123.xml'):
        log.info("Starting provision")
        log.debug("Provision content: {}".format(provision_content))

        provision_action = 'provision'
        url = self._connection.create_soap_service_url(NE3SService.BULK)

        provision_soap = templates.get_file_content('cert_provision.txt', 'r')

        cid_soap = '0.6c9b1d38dec2901c4b97bea78eaecb87a227def4119ce08f@apache.org'
        cid_provision = '92553ee5-ece1-47b4-90de-d7d6816df781@example.jaxws.sun.com'

        random_id = primary_document.replace('.xml', '')

        provision_soap = provision_soap.format(
            manager_registration_key=self._connection.REGISTRATION_KEY,
            session_id=self._connection.session_id,
            provision_content='cid:{}'.format(cid_provision),
            manager_id=self._connection.connection_details.manager_id,
            compression=compression,
            primary_document=primary_document,
            operation_id=random_id,
            plan_id=random_id
        )

        log.debug("Provision SOAP: {}".format(provision_soap))

        header_provision = {'Content-ID': '<{}>'.format(cid_provision),
                            'Content-Transfer-Encoding': 'binary'}
        header_soap = {'Content-ID': '<{}>'.format(cid_soap)}

        fields = OrderedDict()
        fields[cid_soap] = (cid_soap, provision_soap, 'text/xml', header_soap)
        fields[cid_provision] = (cid_provision, provision_content, 'text',
                                 header_provision)

        provision_response = self._connection.send_multipart_soap_message(
            url, fields, action=provision_action)

        log.info("Provision message sent correctly and accepted")
        log.debug("Provision response content {}".format(provision_response))

        return provision_response

    def delete_cert(self, cert_dist_name, cert_fingerprint, timeout):
        stream_name = "CERT.delete_cert"
        cert_delete_stream = self.add_new_msg_stream(stream_name=stream_name,
                                                     msg_list=[CertOperationNotification])
        try:
            provision_content = templates.get_file_content('cert_delete.txt', 'r')

            dist_name = '{cert_dist_name}/CACERT-{cert_fingerprint}'.format(
                cert_dist_name=cert_dist_name,
                cert_fingerprint=cert_fingerprint)

            provision_content = provision_content.format(
                dist_name=dist_name,
            )

            self.cert_provision(provision_content=provision_content)
            notification = cert_delete_stream.get(timeout)

            if not self._is_validation_successful(notification):
                raise OperationFailed(notification.attachment)

        except StreamTimeoutError as e:
            err_msg = "Certificate removal confirmation was not provided in requested time, Error: {}".format(e)
            raise OperationTimeout(err_msg)

        finally:
            self.remove_msg_stream(stream_name=stream_name)

    def _generate_fingerprint(self, path_to_cert):
        cert_file_string = open(path_to_cert)
        cert = x509.load_pem_x509_certificate(cert_file_string.read().encode('utf-8'), default_backend())
        raw_fp = hexlify(cert.fingerprint(hashes.SHA1()))
        cert_file_string.close()
        return raw_fp.decode('utf-8').upper()

    def _convert_to_tar_archive_string(self, list_of_files, cert_filename, provision_filename):
        file_out = BIO()
        provision_xml_file = BIO(list_of_files[0].encode('utf-8'))
        certificate_file = BIO(list_of_files[1].encode('utf-8'))
        info_provision = tarfile.TarInfo(name=provision_filename)
        info_certificate = tarfile.TarInfo(name=cert_filename)
        info_provision.size = len(list_of_files[0])
        info_certificate.size = len(list_of_files[1])

        tar_repo = tarfile.open(fileobj=file_out, mode='w')
        tar_repo.addfile(tarinfo=info_provision, fileobj=provision_xml_file)
        tar_repo.addfile(tarinfo=info_certificate, fileobj=certificate_file)

        tar_repo.close()
        return file_out.getvalue()

    def _return_certificate_content(self, path_to_certificate):
        with open(path_to_certificate) as file:
            certificate_content = file.read()
        return certificate_content

    def initialize_certificate(self, dist_name, timeout, server_type):
        self.update_state(
            dist_name=dist_name,
            mo_class=self.CMP,
            state=self.CMP_INITIALIZATION_REQUEST,
            msg_list=[CMPOperationNotification],
            timeout=timeout,
            server_type=server_type)

    def update_certificate(self, dist_name, timeout, server_type):
        self.update_state(
            dist_name=dist_name,
            mo_class=self.CMP,
            state=self.CMP_KEY_UPDATE_REQUEST,
            msg_list=[CMPOperationNotification],
            timeout=timeout,
            server_type=server_type)

    def update_certificate_revocation_list(self, dist_name, timeout):
        self.update_state(
            dist_name=dist_name,
            mo_class=self.CRLH,
            state=self.CRL_UPDATE_REQUEST,
            msg_list=[CRLOperationNotification],
            timeout=timeout)

    def update_state(self, dist_name, mo_class, state, msg_list, timeout, server_type=None):
        stream_name = "CERT.update_cert_state"

        stream = self.add_new_msg_stream(stream_name=stream_name,
                                         msg_list=msg_list)
        try:
            provision_content = templates.get_file_content('cert_state.txt', 'r')
            server_type_node = '<p name="serverType">{}</p>'.format(server_type) if server_type else ''
            provision_content = provision_content.format(
                dist_name=dist_name,
                state=str(state),
                mo_class=mo_class,
                server_type_node=server_type_node
            )

            random_number = randint(int(10e4), int(10e5))
            provision_filename = 'cert_provision_content{}.xml'.format(random_number)
            log.info("Provision content: {}".format(provision_content))

            self.cert_provision(provision_content=provision_content, compression='none',
                                primary_document=provision_filename)

            notification = stream.get(timeout)

            if not self._is_cmp_crl_validation_successful(notification):
                raise OperationFailed(notification.attachment)

        except StreamTimeoutError as e:
            err_msg = "Certificate state update confirmation was not provided in requested time, Error: {}".format(e)
            raise OperationTimeout(err_msg)

        finally:
            self.remove_msg_stream(stream_name=stream_name)

    def configure_cmp_server(self, dist_name, pre_shared_key, reference_number, timeout, server_type=None):
        stream_name = "CERT.configure_cmp_server"

        stream = self.add_new_msg_stream(stream_name=stream_name,
                                         msg_list=[CMPOperationNotification])
        try:
            provision_content = templates.get_file_content('cmp_settings.txt', 'r')
            server_type_node = '<p name="serverType">{}</p>'.format(server_type) if server_type else ''
            provision_content = provision_content.format(
                dist_name=dist_name,
                pre_shared_key=pre_shared_key,
                ref_num=str(reference_number),
                server_type_node=server_type_node,
                mo_class=self.CMP
            )

            random_number = randint(int(10e4), int(10e5))
            provision_filename = 'cert_provision_content{}.xml'.format(random_number)

            self.cert_provision(provision_content=provision_content, compression='none',
                                primary_document=provision_filename)

            notification = stream.get(timeout)

            if not self._is_cmp_crl_validation_successful(notification):
                raise OperationFailed(notification.attachment)

        except StreamTimeoutError as e:
            err_msg = "CMP settings update confirmation was not provided in requested time, Error: {}".format(e)
            raise OperationTimeout(err_msg)

        finally:
            self.remove_msg_stream(stream_name=stream_name)
